src/inventory.js.content:
export function createInventory(products) {
  const stock = new Map(products.map((product) => [product.id, product.stock]));

  function available(productId) {
    if (!stock.has(productId)) throw new Error('PRODUCT_NOT_FOUND');
    return stock.get(productId);
  }

  return {
    available,
    allocate(productId, quantity) {
      if (!Number.isSafeInteger(quantity) || quantity <= 0) {
        throw new Error('INVALID_QUANTITY');
      }
      const remaining = available(productId) - quantity;
      if (remaining < 0) throw new Error('OUT_OF_STOCK');
      stock.set(productId, remaining);
    },
    release(productId, quantity) {
      stock.set(productId, available(productId) + quantity);
    },
  };
}

src/pricing.js.content:
export function calculateOrder(lines) {
  let subtotalCents = 0;
  for (const line of lines) {
    subtotalCents += line.priceCents * line.quantity;
  }
  const shippingCents = subtotalCents >= 7500 ? 0 : 499;
  return { subtotalCents, shippingCents, totalCents: subtotalCents + shippingCents };
}

src/reservations.js.content:
import { randomUUID } from 'node:crypto';
import { reservationLifetimeMs } from './config.js';

export function createReservations(inventory, now = Date.now) {
  const reservations = new Map();

  function expireAt(timestamp) {
    for (const reservation of reservations.values()) {
      if (reservation.status === 'active' && timestamp >= reservation.expiresAt) {
        reservation.status = 'expired';
        inventory.release(reservation.productId, reservation.quantity);
      }
    }
  }

  return {
    reserve(productId, quantity) {
      const timestamp = now();
      expireAt(timestamp);
      const lifetime = reservationLifetimeMs();
      inventory.allocate(productId, quantity);
      const reservation = {
        id: randomUUID(),
        productId,
        quantity,
        expiresAt: timestamp + lifetime,
        status: 'active',
      };
      reservations.set(reservation.id, reservation);
      return { ...reservation };
    },
    checkout(id) {
      expireAt(now());
      const reservation = reservations.get(id);
      if (!reservation) throw new Error('RESERVATION_NOT_FOUND');
      if (reservation.status === 'expired') throw new Error('RESERVATION_EXPIRED');
      if (reservation.status !== 'active') throw new Error('ALREADY_CHECKED_OUT');
      reservation.status = 'checked-out';
      return { ...reservation };
    },
    available(productId) {
      expireAt(now());
      return inventory.available(productId);
    },
  };
}

src/shop.js.content:
import { catalog } from './catalog.js';
import { createInventory } from './inventory.js';
import { createReservations } from './reservations.js';
import { calculateOrder } from './pricing.js';

export function createShop({ now = Date.now } = {}) {
  const products = new Map(catalog.map((product) => [product.id, product]));
  const reservations = createReservations(createInventory(catalog), now);

  return {
    reserve: reservations.reserve,
    available: reservations.available,
    checkout(reservationId) {
      const reservation = reservations.checkout(reservationId);
      const product = products.get(reservation.productId);
      const lines = [{
        productId: product.id,
        priceCents: product.priceCents,
        quantity: reservation.quantity,
      }];
      return { reservationId, lines, ...calculateOrder(lines) };
    },
  };
}

test/pricing.test.js.content:
import assert from 'node:assert/strict';
import test from 'node:test';
import { calculateOrder } from '../src/pricing.js';

test('line amounts contribute to the order subtotal', () => {
  assert.deepEqual(calculateOrder([
    { priceCents: 1500, quantity: 2 },
    { priceCents: 900, quantity: 3 },
  ]), { subtotalCents: 5700, shippingCents: 499, totalCents: 6199 });
});

test('delivery pricing follows the merchandise subtotal', () => {
  for (const subtotal of [7499, 7500, 7501]) {
    const order = calculateOrder([{ priceCents: subtotal, quantity: 1 }]);
    assert.equal(order.shippingCents, subtotal < 7500 ? 499 : 0);
    assert.equal(order.totalCents, subtotal + order.shippingCents);
  }
});

test/shop.test.js.content:
import assert from 'node:assert/strict';
import test from 'node:test';
import { createShop } from '../src/shop.js';

test('orders include merchandise and delivery amounts', () => {
  const shop = createShop();
  const reservation = shop.reserve('notebook', 2);
  const order = shop.checkout(reservation.id);
  assert.equal(order.subtotalCents, 3000);
  assert.equal(order.shippingCents, 499);
  assert.equal(order.totalCents, 3499);
  assert.equal(shop.available('notebook'), 6);
});

test('large orders include delivery', () => {
  const shop = createShop();
  const order = shop.checkout(shop.reserve('notebook', 5).id);
  assert.equal(order.shippingCents, 0);
  assert.equal(order.totalCents, 7500);
});

test('invalid quantities leave stock unchanged', () => {
  const shop = createShop();
  for (const quantity of [0, -1, 1.5, NaN, '2']) {
    assert.throws(() => shop.reserve('notebook', quantity), /INVALID_QUANTITY/);
  }
  assert.equal(shop.available('notebook'), 8);
});

test('unavailable products and quantities are rejected', () => {
  const shop = createShop();
  assert.throws(() => shop.reserve('unknown', 1), /PRODUCT_NOT_FOUND/);
  assert.throws(() => shop.reserve('notebook', 9), /OUT_OF_STOCK/);
  assert.equal(shop.available('notebook'), 8);
});

test('an order consumes its reservation once', () => {
  const shop = createShop();
  const reservation = shop.reserve('pen-set', 2);
  shop.checkout(reservation.id);
  assert.throws(() => shop.checkout(reservation.id), /ALREADY_CHECKED_OUT/);
  assert.equal(shop.available('pen-set'), 10);
});

test('abandoned reservations return stock', () => {
  let timestamp = 10000;
  const shop = createShop({ now: () => timestamp });
  const reservation = shop.reserve('notebook', 2);
  timestamp += 20 * 60 * 1000;
  assert.throws(() => shop.checkout(reservation.id), /RESERVATION_EXPIRED/);
  assert.equal(shop.available('notebook'), 8);
  assert.equal(shop.available('notebook'), 8);
});

test('checkout requires a known reservation', () => {
  assert.throws(() => createShop().checkout('missing'), /RESERVATION_NOT_FOUND/);
});

test('returned reservation data does not change stored state', () => {
  const shop = createShop();
  const reservation = shop.reserve('pen-set', 1);
  reservation.quantity = 100;
  assert.equal(shop.checkout(reservation.id).lines[0].quantity, 1);
});
